import{_ as t,o,c as a,ah as n}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"MASTER DOSSIER: THE HORTEN MYSTERY","description":"","frontmatter":{},"headers":[],"relativePath":"en/Premium_Dossier_Master.md","filePath":"en/Premium_Dossier_Master.md"}'),r={name:"en/Premium_Dossier_Master.md"};function i(s,e,h,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="master-dossier-the-horten-mystery" tabindex="-1">MASTER DOSSIER: THE HORTEN MYSTERY <a class="header-anchor" href="#master-dossier-the-horten-mystery" aria-label="Permalink to &quot;MASTER DOSSIER: THE HORTEN MYSTERY&quot;">​</a></h1><h2 id="an-investigative-mockumentary-by-volti-sodala" tabindex="-1">An Investigative Mockumentary by Volti Sodala <a class="header-anchor" href="#an-investigative-mockumentary-by-volti-sodala" aria-label="Permalink to &quot;An Investigative Mockumentary by Volti Sodala&quot;">​</a></h2><h2 id="as-of-march-1-2026" tabindex="-1"><strong>As of:</strong> March 1, 2026 <a class="header-anchor" href="#as-of-march-1-2026" aria-label="Permalink to &quot;**As of:** March 1, 2026&quot;">​</a></h2><h3 id="table-of-contents" tabindex="-1">TABLE OF CONTENTS <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;TABLE OF CONTENTS&quot;">​</a></h3><ol><li>The Concept</li><li>The Screenplay (Parts 1-4)</li><li>The Research Archive</li><li>Secret Media &amp; Documents</li></ol><hr><h1 id="the-concept-the-horten-mystery" tabindex="-1">The Concept: The Horten Mystery <a class="header-anchor" href="#the-concept-the-horten-mystery" aria-label="Permalink to &quot;The Concept: The Horten Mystery&quot;">​</a></h1><p><strong>Working Title:</strong> <em>The Horten Mystery: A Fabulous Fiction of Power, Money, and Pearls</em></p><h2 id="the-vision" tabindex="-1">The Vision <a class="header-anchor" href="#the-vision" aria-label="Permalink to &quot;The Vision&quot;">​</a></h2><p>This mockumentary is a satirical and at the same time profound examination of the legacy of one of the richest and most controversial couples in German-Austrian history: Heidi and Helmut Horten.</p><p>We combine historical facts with fictional elements to show the absurdity of extreme wealth, the mechanisms of displacement, and the intertwining of capital and politics.</p><h2 id="the-structure-4-parts" tabindex="-1">The Structure (4 Parts) <a class="header-anchor" href="#the-structure-4-parts" aria-label="Permalink to &quot;The Structure (4 Parts)&quot;">​</a></h2><h3 id="_1-the-dazzling-widow" tabindex="-1">1. The Dazzling Widow <a class="header-anchor" href="#_1-the-dazzling-widow" aria-label="Permalink to &quot;1. The Dazzling Widow&quot;">​</a></h3><p>A look at Heidi&#39;s life after her husband&#39;s death. We show her eccentric luxury, her art collection, and her role as the &quot;Grande Dame&quot; of society.</p><h3 id="_2-the-rise-of-helmut-horten" tabindex="-1">2. The Rise of Helmut Horten <a class="header-anchor" href="#_2-the-rise-of-helmut-horten" aria-label="Permalink to &quot;2. The Rise of Helmut Horten&quot;">​</a></h3><p>We document Helmut&#39;s path to becoming the &quot;department store king.&quot; The focus here is on the &quot;market consolidation&quot; (Aryanization) of the 1930s.</p><h3 id="_3-the-fate-of-the-losers" tabindex="-1">3. The Fate of the Losers <a class="header-anchor" href="#_3-the-fate-of-the-losers" aria-label="Permalink to &quot;3. The Fate of the Losers&quot;">​</a></h3><p>What happened to those who had to give up their department stores? We highlight the fate of the Alsberg brothers and other victims.</p><h3 id="_4-the-political-love-story" tabindex="-1">4. The Political Love Story <a class="header-anchor" href="#_4-the-political-love-story" aria-label="Permalink to &quot;4. The Political Love Story&quot;">​</a></h3><p>The relationship with the Austrian People&#39;s Party (ÖVP). We dedicate ourselves to the &quot;Rain of Gold&quot; – the donations and the systematic splitting of payments.</p><hr><p><em>This project is a balancing act between documentation and satire.</em></p><h1 id="part-1-the-dazzling-widow" tabindex="-1">Part 1: The Dazzling Widow <a class="header-anchor" href="#part-1-the-dazzling-widow" aria-label="Permalink to &quot;Part 1: The Dazzling Widow&quot;">​</a></h1><p><strong>Working Title:</strong> <em>From the Glow of Silence</em></p><p><strong>Cast:</strong> Birgit Minichmayr (Heidi Horten), August Diehl (The Young Helmut - in flashbacks), Udo Samel (August Wöginger), Oliver Masucci (The Curator/Chronicler).</p><hr><h2 id="scene-1-the-archive-of-the-smile" tabindex="-1">Scene 1: The Archive of the Smile <a class="header-anchor" href="#scene-1-the-archive-of-the-smile" aria-label="Permalink to &quot;Scene 1: The Archive of the Smile&quot;">​</a></h2><p><strong>Location:</strong> A state-of-the-art, air-conditioned depot near Klagenfurt. <strong>Time:</strong> Present day.</p><p>White gloves sit on polished tables everywhere. The camera glides over endless rows of jewelry boxes. Heidi (Birgit Minichmayr) enters the frame. She wears a simple but priceless silk dress. She opens one box after another.</p><p><strong>HEIDI</strong> (quietly, almost tenderly) This is not just jewelry. These are preserved moments. Helmut always said: &quot;Heidi, gold doesn&#39;t cry.&quot; He was right. It just continues to shine, no matter what happens outside.</p><p>She takes out a necklace; the pearls shimmer in the artificial light.</p><p><strong>HEIDI (Cont&#39;d)</strong> See this pearl? It&#39;s a dot. A small, white dot in an infinite balance sheet. If you have enough of them, you don&#39;t see the image anymore. You only see the light. That is my pointillism.</p><hr><h2 id="scene-2-the-pearl-inventory-tango" tabindex="-1">Scene 2: The Pearl Inventory Tango <a class="header-anchor" href="#scene-2-the-pearl-inventory-tango" aria-label="Permalink to &quot;Scene 2: The Pearl Inventory Tango&quot;">​</a></h2><p><strong>Location:</strong> The large mirrored hall in the palace. <strong>Time:</strong> A sleepless night.</p><p>Heidi spreads thousands of pearls on a huge black velvet cloth. She begins to sort them with silver tweezers. The rhythm of her movements becomes almost dance-like. In the background, a distorted version of a waltz plays quietly.</p><p><strong>HEIDI</strong> (to an imaginary person) One for the foundation. One for the art. Three for the silence. And one... for eternity.</p><p>The Curator (Oliver Masucci) watches her from the shadows.</p><p><strong>CURATOR</strong> Madame, the list of donation requests has grown. Politics is knocking. They want... rain again.</p><p><strong>HEIDI</strong> (without looking up) Then we give them rain, Curator. But only in drops. Piece by piece. Like these pearls. If you give everything at once, they drown. If you split it, gratitude grows.</p><hr><h2 id="scene-3-the-silence-of-the-yachts" tabindex="-1">Scene 3: The Silence of the Yachts <a class="header-anchor" href="#scene-3-the-silence-of-the-yachts" aria-label="Permalink to &quot;Scene 3: The Silence of the Yachts&quot;">​</a></h2><p><strong>Location:</strong> Deck of the <em>Carinthia VII</em>, off the coast of Nice. <strong>Time:</strong> Sunset.</p><p>The camera shows the massive dimensions of the yacht. It is so quiet that you only hear the gentle hum of the generators. Heidi sits at the stern, staring at the wake.</p><p><strong>HEIDI</strong> Helmut loved the sea. He said water has no memory. You can draw a trail, and seconds later it&#39;s gone. That is the freedom of money. It erases the traces of its own creation.</p><p>A steward serves champagne in crystal glasses so thin they seem like they would break just by looking at them.</p><p><strong>HEIDI (Cont&#39;d)</strong> Do you know what the problem with history is? It&#39;s too loud. It gathers dust. Wealth, on the other hand, is clinically clean. It smells of nothing. Except for tomorrow.</p><hr><h2 id="scene-4-the-heidi-gala-–-the-staging-of-nothingness" tabindex="-1">Scene 4: The Heidi Gala – The Staging of Nothingness <a class="header-anchor" href="#scene-4-the-heidi-gala-–-the-staging-of-nothingness" aria-label="Permalink to &quot;Scene 4: The Heidi Gala – The Staging of Nothingness&quot;">​</a></h2><p><strong>Location:</strong> A magnificent ballroom. <strong>Time:</strong> Night.</p><p>Dozens of guests in evening attire are standing around. But there is no music, no conversation. Only the clicking of heels on the marble. Heidi walks through the silent crowd like a ghost.</p><p><strong>HEIDI</strong> (voice-over) People think a gala is about showing off. But the true gala is the silence that follows. The moment when the guests go home and you are left with the inventory of the night. That&#39;s when you see who really belongs to you.</p><hr><h1 id="part-2-the-rise-of-helmut-horten" tabindex="-1">Part 2: The Rise of Helmut Horten <a class="header-anchor" href="#part-2-the-rise-of-helmut-horten" aria-label="Permalink to &quot;Part 2: The Rise of Helmut Horten&quot;">​</a></h1><p><strong>Working Title:</strong> <em>The Bargain Hunter</em></p><p><strong>Cast:</strong> August Diehl (Helmut Horten), Oliver Masucci (The Bankier / The Shredder), Birgit Minichmayr (The Secretary / The Conscience).</p><hr><h2 id="scene-10-the-office-of-calculation" tabindex="-1">Scene 10: The Office of Calculation <a class="header-anchor" href="#scene-10-the-office-of-calculation" aria-label="Permalink to &quot;Scene 10: The Office of Calculation&quot;">​</a></h2><p><strong>Location:</strong> A dark office in Duisburg. <strong>Time:</strong> 1938.</p><p>Helmut (August Diehl) sits at a massive oak desk. He is 27 years old. In front of him lies the file &quot;Alsberg&quot;. He doesn&#39;t look like a revolutionary, but like a bookkeeper of power.</p><p><strong>HELMUT</strong> (to his secretary) The price is too high. 2.5 million? That&#39;s not a bargain. That&#39;s a gift. And I don&#39;t give gifts.</p><p><strong>SECRETARY</strong> But Mr. Horten, the family is under pressure. They have to sell. They need the money for their... papers.</p><p><strong>HELMUT</strong> (coldly) Then their pressure is my profit. That&#39;s not my fault. That&#39;s the market. Re-write the contract. 800,000. And put it on a blocked account. I don&#39;t want to see the money leave the country.</p><hr><h2 id="scene-11-the-clearing-of-the-shelves" tabindex="-1">Scene 11: The Clearing of the Shelves <a class="header-anchor" href="#scene-11-the-clearing-of-the-shelves" aria-label="Permalink to &quot;Scene 11: The Clearing of the Shelves&quot;">​</a></h2><p><strong>Location:</strong> The Alsberg department store at night. <strong>Time:</strong> 1938.</p><p>Workers are removing the letters &quot;ALSBERG&quot; from the facade. Helmut stands below and watches. He is eating an apple. The letters fall onto the sidewalk with a metallic clang.</p><p><strong>HELMUT</strong> (to himself) A name is just a collection of letters. If you change the order, the world changes. Tomorrow, it will say HORTEN. And nobody will remember what was there before.</p><hr><h1 id="part-3-the-fate-of-the-losers" tabindex="-1">Part 3: The Fate of the Losers <a class="header-anchor" href="#part-3-the-fate-of-the-losers" aria-label="Permalink to &quot;Part 3: The Fate of the Losers&quot;">​</a></h1><p><strong>Working Title:</strong> <em>Vom Verschwinden der Namen</em></p><p><strong>Cast:</strong> Oliver Masucci (Alfred Alsberg / Heinz Alsberg), August Diehl (The young Helmut / A fictional restitution official), Birgit Minichmayr (Martha Alsberg / The voice of the present).</p><hr><h2 id="scene-15-the-protocol-of-silence" tabindex="-1">Scene 15: The Protocol of Silence <a class="header-anchor" href="#scene-15-the-protocol-of-silence" aria-label="Permalink to &quot;Scene 15: The Protocol of Silence&quot;">​</a></h2><p><strong>Location:</strong> A small, overcrowded apartment in Amsterdam. <strong>Time:</strong> 1939.</p><p>Alfred Alsberg (Oliver Masucci) sits at a shaky table. He tries to make a list of his remaining property. His wife Martha (Birgit Minichmayr) is packing silverware in newspaper.</p><p><strong>ALFRED</strong> (bitterly) They called the department store in Duisburg &quot;Horten&quot; now. They didn&#39;t even change the facade. Just the letters above the door. As if you could just remove a soul with sandpaper.</p><p><strong>MARTHA</strong> We are safe here, Alfred. Helmut Horten is far away. He has what he wanted. He won&#39;t follow us.</p><hr><h2 id="scene-16-the-kafkaesque-office-of-restitution" tabindex="-1">Scene 16: The Kafkaesque Office of Restitution <a class="header-anchor" href="#scene-16-the-kafkaesque-office-of-restitution" aria-label="Permalink to &quot;Scene 16: The Kafkaesque Office of Restitution&quot;">​</a></h2><p><strong>Location:</strong> A gray, dusty office in the post-war period (1952). <strong>Time:</strong> An endless afternoon.</p><p>Heinz Alsberg (Oliver Masucci) sits opposite an official (August Diehl). The official wears arm protectors and smokes a cigar that smells of cheap state service. Heinz places a tattered copy of the Aryanization protocol of May 1, 1938 on the table.</p><p><strong>HEINZ</strong> Here it is. The protocol of the takeover. My father signed it under duress. He handed it to me before his deportation to Litzmannstadt. &quot;This paper is our right,&quot; he said.</p><p><strong>OFFICIAL</strong> (picks up the paper with two fingers as if it were unclean) Litzmannstadt... yes, tragic. But this document, Mr. Alsberg... this is only a declaration of intent. Where is the main notarial contract? Where is the proof that the purchase price didn&#39;t flow after all?</p><p><strong>HEINZ</strong> The purchase price was in a blocked account! Helmut Horten knew that we would never get the money. He pacted with the state to starve us!</p><p><strong>OFFICIAL</strong> (smiles pityingly) Pacting is a harsh word. Let&#39;s call it... cooperation in difficult times. Mr. Horten is a respected taxpayer, he rebuilt Duisburg after the war. We cannot jeopardize his reputation with such... emotional allegations.</p><hr><h1 id="part-4-the-political-love-story" tabindex="-1">Part 4: The Political Love Story <a class="header-anchor" href="#part-4-the-political-love-story" aria-label="Permalink to &quot;Part 4: The Political Love Story&quot;">​</a></h1><p><strong>Working Title:</strong> <em>The Rain of Gold</em></p><p><strong>Cast:</strong> Birgit Minichmayr (Heidi Horten), Oliver Masucci (The General Secretary / PR Consultant / Christian Pilnacek), August Diehl (The Investigative Reporter / Helmut Horten / Gernot Blümel), <strong>Udo Samel</strong> (August Wöginger).</p><hr><h2 id="scene-1-the-backroom-of-splendor" tabindex="-1">Scene 1: The Backroom of Splendor <a class="header-anchor" href="#scene-1-the-backroom-of-splendor" aria-label="Permalink to &quot;Scene 1: The Backroom of Splendor&quot;">​</a></h2><p><strong>Location:</strong> A gilded private room in a noble Viennese café. <strong>Time:</strong> Election year 2017.</p><p>Heidi (Birgit Minichmayr) sits relaxed in a velvet armchair. In front of her lies a checkbook, enthroned on the table like a relic. The General Secretary (Oliver Masucci) leans forward in awe.</p><p><strong>GENERAL SECRETARY</strong> We need... stability, Madame. And stability costs in these times. The posters, the online ads... the consultants...</p><p><strong>HEIDI</strong> (smiles) I love stability. Helmut used to say: &quot;Money is the glue that holds society together.&quot; But if you use too much glue, you can&#39;t see the joints anymore.</p><hr><h2 id="scene-2-the-sketch-of-donation-splitting-new" tabindex="-1">Scene 2: The Sketch of &quot;Donation Splitting&quot; (NEW) <a class="header-anchor" href="#scene-2-the-sketch-of-donation-splitting-new" aria-label="Permalink to &quot;Scene 2: The Sketch of &quot;Donation Splitting&quot; (NEW)&quot;">​</a></h2><p><strong>Location:</strong> An office full of shredders and calculators. <strong>Time:</strong> Late at night.</p><p>Three consultants in tailor-made suits (Masucci, Diehl, Minichmayr in multiple roles) sit around a mountain of 500-euro bills. They have a template in front of them.</p><p><strong>CONSULTANT 1 (Masucci)</strong> Here we have a total of 931,000 euros from Madame. Almost a million! A magnificent chunk. But in one piece... in one piece it&#39;s indigestible for the Court of Audit.</p><p><strong>CONSULTANT 2 (Diehl)</strong> We need the scalpel. We cut it into exactly 49,000-euro portions. Not 50,000! At 50,000 the sirens go off. At 49,000... there is holy silence.</p><p><strong>CONSULTANT 3 (Minichmayr)</strong> It&#39;s like pointillism! 19 times 49,000 euros. Many small dots. When you stand in front of it, you only see a lot of nice, discrete individual donations. Only when you move far away do you see... the empire.</p><hr><h2 id="scene-3-the-rain-of-gold-in-parliament-new" tabindex="-1">Scene 3: The Rain of Gold in Parliament (NEW) <a class="header-anchor" href="#scene-3-the-rain-of-gold-in-parliament-new" aria-label="Permalink to &quot;Scene 3: The Rain of Gold in Parliament (NEW)&quot;">​</a></h2><p><strong>Location:</strong> The plenary chamber of the Austrian National Council. <strong>Time:</strong> A fictional, surreal debate on transparency.</p><p>An MP (August Diehl) gives a passionate speech on the &quot;innocence of the donor.&quot; Suddenly, it begins to rain from the ceiling. But it&#39;s not water, it&#39;s golden confetti coins with Heidi&#39;s likeness. Each coin bears the imprint &quot;49,000.&quot;</p><p><strong>MP</strong> (while catching the coins) See? This is not money! This is... appreciation! This is civic engagement in its purest, minted form! Who are we to bite the hand that fragments us so wonderfully?</p><p>The other MPs begin to catch the coins with umbrellas held upside down.</p><hr><h2 id="scene-4-the-interview-of-forgetting-new" tabindex="-1">Scene 4: The Interview of Forgetting (NEW) <a class="header-anchor" href="#scene-4-the-interview-of-forgetting-new" aria-label="Permalink to &quot;Scene 4: The Interview of Forgetting (NEW)&quot;">​</a></h2><p><strong>Location:</strong> A yacht in the Mediterranean. <strong>Time:</strong> Present.</p><p>Heidi is interviewed by an investigative journalist (August Diehl). The journalist looks exhausted, Heidi is radiant.</p><p><strong>JOURNALIST</strong> Mrs. Horten, critics say you buy political influence with your donations. 931,000 euros is no small change.</p><p><strong>HEIDI</strong> (laughs brightly) Buy? That&#39;s such a... commercial term. I call it &quot;enabling.&quot; I enable politicians to concentrate on the essentials without having to worry about their budget. Isn&#39;t that the epitome of freedom?</p><hr><h2 id="scene-5-the-transparency-gala-–-the-pinnacle-of-satire-new" tabindex="-1">Scene 5: The &quot;Transparency Gala&quot; – The Pinnacle of Satire (NEW) <a class="header-anchor" href="#scene-5-the-transparency-gala-–-the-pinnacle-of-satire-new" aria-label="Permalink to &quot;Scene 5: The &quot;Transparency Gala&quot; – The Pinnacle of Satire (NEW)&quot;">​</a></h2><p><strong>Location:</strong> A magnificent ballroom celebrating &quot;Transparency&quot; as its theme. <strong>Time:</strong> A fictional gala event.</p><p>Each guest wears a mask made of semi-transparent plastic. You can see the faces, but they are distorted.</p><p><strong>NARRATOR (Masucci, Voice-over)</strong> They celebrated openness while they closed the doors. They called it &quot;new style&quot; while they refined Helmut&#39;s old recipes. Heidi sat in the middle, the sun of her own system. Each 49,000-euro tranche on her necklace corresponded to a small token of appreciation to a political section.</p><p>Heidi dances with a minister. She whispers something in his ear. He nods vigorously, as if receiving a divine inspiration.</p><hr><h2 id="scene-6-the-court-of-audit-nightmare-new" tabindex="-1">Scene 6: The &quot;Court of Audit Nightmare&quot; (NEW) <a class="header-anchor" href="#scene-6-the-court-of-audit-nightmare-new" aria-label="Permalink to &quot;Scene 6: The &quot;Court of Audit Nightmare&quot; (NEW)&quot;">​</a></h2><p><strong>Location:</strong> A dark archive where a lonely auditor (Oliver Masucci) tries to trace the donation paths. <strong>Time:</strong> Night.</p><p>The file folders begin to move by themselves. Numbers hop off the pages and form patterns on the walls.</p><p><strong>AUDITOR</strong> It&#39;s a labyrinth of silk and gold! You follow a 49,000-euro donation and end up at an equestrian event in Carinthia. You follow the equestrian event and end up at an art event in Vienna. And in the end... in the end there is always only one name. But the name is legal. It&#39;s so legal it hurts.</p><p>He is buried by a mountain of golden &quot;dots.&quot;</p><hr><h2 id="scene-7-the-finale-–-the-eternity-of-capital-new" tabindex="-1">Scene 7: The Finale – The Eternity of Capital (NEW) <a class="header-anchor" href="#scene-7-the-finale-–-the-eternity-of-capital-new" aria-label="Permalink to &quot;Scene 7: The Finale – The Eternity of Capital (NEW)&quot;">​</a></h2><p><strong>Location:</strong> Heidi&#39;s mausoleum or a modern art gallery. <strong>Time:</strong> In the near future.</p><p>We see a giant screen. Helmut Horten is depicted on it, but the image consists of millions of small euro symbols. Heidi steps in front of it.</p><p><strong>HEIDI</strong> (to the audience) Helmut said capital never dies. He was right. It only changes its form. It used to be department stores, today it&#39;s parliaments. It used to be &quot;market adjustment,&quot; today it&#39;s &quot;policy making.&quot; But the pointillism remains the same.</p><p>She presses a button. The image of Helmut changes into the logo of a political party and then back again.</p><hr><h2 id="scene-8-the-burial-of-silence-and-the-fear-in-linz" tabindex="-1">Scene 8: The Burial of Silence (and the Fear in Linz) <a class="header-anchor" href="#scene-8-the-burial-of-silence-and-the-fear-in-linz" aria-label="Permalink to &quot;Scene 8: The Burial of Silence (and the Fear in Linz)&quot;">​</a></h2><p><strong>Location:</strong> An exclusive funeral service at Lake Wörthersee. White marble, black bows, champagne coolers. <strong>Time:</strong> June 2022 (flashback) / Cut to March 2026 (present).</p><p>August Wöginger (Udo Samel) stands at the buffet. He doesn&#39;t look nervous, but rather... deliberate. He eats a sandwich with a knife and fork. He speaks quietly on the phone. In the background, the magnificent photo of Heidi.</p><p><strong>WÖGINGER</strong> (into the phone, with a gentle Upper Austrian accent) Yes, hello... no, I&#39;m at the lake right now. We&#39;re saying goodbye to the Madame. Yes, the 931,000... it&#39;s all properly booked. In tranches, as we discussed. Pointillism, exactly.</p><p>He looks at the photo of Heidi and raises his wine glass minimally.</p><p><strong>WÖGINGER</strong> Regarding Linz... Tuesday, March 3rd. I&#39;ve already told the judge: I&#39;m not an inciter. I&#39;m an enabler. If Thomas Schmid asks me who we need in Braunau, I tell him. That&#39;s living proximity to the citizens. The WKStA simply doesn&#39;t understand rural structures.</p><hr><h2 id="scene-9-the-ghost-hour-of-balances-new" tabindex="-1">Scene 9: The Ghost Hour of Balances (NEW) <a class="header-anchor" href="#scene-9-the-ghost-hour-of-balances-new" aria-label="Permalink to &quot;Scene 9: The Ghost Hour of Balances (NEW)&quot;">​</a></h2><p><strong>Location:</strong> Heidi&#39;s empty bedroom. <strong>Time:</strong> Night.</p><p>Wöginger (Udo Samel) sneaks through the room. He looks almost like an antique dealer here, someone who appreciates the value of silence. He touches a silk curtain. Heidi&#39;s ghost (Birgit Minichmayr) appears in the mirror.</p><p><strong>HEIDI (GHOST)</strong> August... you&#39;re worried about a tax office in the Innviertel? I repainted entire sections with gold.</p><p><strong>WÖGINGER</strong> (calmly, without turning around) Madame, your world was... generous. My world today is... petty. Thomas Schmid is singing in Vienna now, and in Linz they want to know why a mayor should be better qualified than an official. They don&#39;t understand that loyalty is a qualification in its own right.</p><p><strong>HEIDI (GHOST)</strong> Then teach them, August. Teach them the aesthetics of favor. In 49,000 steps.</p><hr><h2 id="scene-10-the-art-of-regional-intervention-new" tabindex="-1">Scene 10: The Art of Regional Intervention (NEW) <a class="header-anchor" href="#scene-10-the-art-of-regional-intervention-new" aria-label="Permalink to &quot;Scene 10: The Art of Regional Intervention (NEW)&quot;">​</a></h2><p><strong>Location:</strong> A back room in a Linz inn. Dark wood, stag antlers. <strong>Time:</strong> March 1, 2026 (Evening).</p><p>August Wöginger (Udo Samel) sits alone at a round regular&#39;s table. In front of him are the printouts of the chats. He wears reading glasses. He speaks to an imaginary judge&#39;s bench.</p><p><strong>WÖGINGER</strong> Judge, look... when I pick up the phone, I do it for the people. The word &quot;intervention&quot; sounds like... backroom. But we in the Innviertel call it &quot;pulling together.&quot; That the mayor gets the post, that was a structural measure. A regional personnel development. That Mrs. Scharf... (he pauses briefly)... has a different conception of qualification, that is her good right. But politics is more than just report card grades.</p><p>He marks a passage in the chat history with a yellow pen. He smiles almost pityingly.</p><p><strong>WÖGINGER</strong> Inciter? No. I am the conductor of a very quiet melody. And on Tuesday... on Tuesday I will hold the baton.</p><p>He closes the file. It makes a dry, final sound.</p><hr><h2 id="scene-11-the-budget-hole-ballet" tabindex="-1">Scene 11: The Budget Hole Ballet <a class="header-anchor" href="#scene-11-the-budget-hole-ballet" aria-label="Permalink to &quot;Scene 11: The Budget Hole Ballet&quot;">​</a></h2><p><strong>Location:</strong> A magnificent hall in parliament. In the background stands the &quot;Sobotka organ.&quot; <strong>Time:</strong> January 2025 (flashback).</p><p>Magnus Brunner (August Diehl) stands in front of a giant screen with graphics that all point steeply downwards. Wolfgang Sobotka (Oliver Masucci) sits at the piano and plays a disharmonious melody.</p><p><strong>BRUNNER</strong> Wolfgang, it&#39;s 4.7 percent. That&#39;s not a hole anymore, it&#39;s a crater. The EU is already sending us love letters from Brussels.</p><p><strong>SOBOTKA</strong> (without looking up from the piano) Magnus, you think too linearly. Think pointillistically! 4.7 percent are only many small decimal places. If you light the graphic correctly, it looks like... art. An abstract work on the transience of tax money.</p><hr><h2 id="scene-12-the-heir-of-stones" tabindex="-1">Scene 12: The Heir of Stones <a class="header-anchor" href="#scene-12-the-heir-of-stones" aria-label="Permalink to &quot;Scene 12: The Heir of Stones&quot;">​</a></h2><p><strong>Location:</strong> An empty, former Horten department store. Dust and scaffolding everywhere. <strong>Time:</strong> Present.</p><p>René Benko (Oliver Masucci in another role) stands in the middle of the empty hall. He stares at an old memorial plaque for Helmut Horten, which hangs half-torn on the wall.</p><p><strong>BENKO</strong> (whispering) Helmut, you had it easy. You had contemporary history on your side. You took the buildings when they were worth nothing. I took them when they were worth everything – at least in my books.</p><p>The ghost of Helmut Horten (August Diehl) steps out of the shadow of an escalator.</p><p><strong>HELMUT (GHOST)</strong> You made the mistake of all gold miners, René. You believed the stones were more important than the silence. I built an empire that outlived me. You built an empire that eats you.</p><p><strong>BENKO</strong> I wanted to complete the pointillism! Billions out of nothing! A mosaic of glass and steel!</p><p><strong>HELMUT (GHOST)</strong> Glass breaks, René. And steel rusts. Only the pearl... only the pearl endures. But you insisted on building skyscrapers.</p><hr><h2 id="scene-13-the-conductor-of-proceedings" tabindex="-1">Scene 13: The Conductor of Proceedings <a class="header-anchor" href="#scene-13-the-conductor-of-proceedings" aria-label="Permalink to &quot;Scene 13: The Conductor of Proceedings&quot;">​</a></h2><p><strong>Location:</strong> A dark, wood-paneled back room in a Viennese pub. <strong>Time:</strong> Late evening (flashback).</p><p>Christian Pilnacek (Oliver Masucci in a double role) sits at a small round table. He looks tired, a glass of wine stands in front of him. Wolfgang Sobotka (August Diehl) leans across the table.</p><p><strong>SOBOTKA</strong> Christian, we have a problem. This WKStA... they&#39;re like terriers. They dig into things that are none of their business. The Horten donations, the Signa valuations... it disturbs the harmony.</p><p><strong>PILNACEK</strong> (with a heavy voice) These are proceedings, Wolfgang. Official investigations. I can&#39;t just...</p><p><strong>SOBOTKA</strong> (unterbruch ihn) Why don&#39;t you just shut it down? Very discretely. A bit of sand in the gears of the bureaucracy. A lost file here, a suspended investigator there. Pointillism, Christian! If you scatter enough small grains of sand, the machine stops.</p><p><strong>PILNACEK</strong> They&#39;re recording everything, Wolfgang. Every word. The walls have developed ears.</p><p><strong>SOBOTKA</strong> (smiles coldly) Then we must play louder. More music, fewer facts. That&#39;s the secret of the mystery.</p><hr><h2 id="scene-14-the-duel-of-the-presidents" tabindex="-1">Scene 14: The Duel of the Presidents <a class="header-anchor" href="#scene-14-the-duel-of-the-presidents" aria-label="Permalink to &quot;Scene 14: The Duel of the Presidents&quot;">​</a></h2><p><strong>Location:</strong> The committee room in parliament. <strong>Time:</strong> January 2026 (present).</p><p>Walter Rosenkranz (Oliver Masucci in a new role) sits at the raised chairman&#39;s table. He looks extremely formal, almost like a Prussian judge. Opposite him sits Wolfgang Sobotka (August Diehl) on the witness stand.</p><p><strong>ROSENKRANZ</strong> (rings the bell) Mr. Sobotka, I must ask you again: Were you aware of the audio recording of Christian Pilnacek before it became public in the &quot;pub&quot;?</p><p><strong>SOBOTKA</strong> (smiles smugly) Mr. President, your question is... how shall I say... a bit transparent. We all know why we are here. You don&#39;t want answers, you want a show.</p><p><strong>ROSENKRANZ</strong> We are here to investigate the &quot;shutting down&quot; of investigations. If this is a show, then it is the show of your party. What did you tell Pilnacek about the Horten donations?</p><p><strong>SOBOTKA</strong> I told him that you shouldn&#39;t shut down music as long as the audience is still dancing.</p><p><strong>ROSENKRANZ</strong> (coldly) The audience in Rossatz is no longer dancing, Mr. Sobotka. There is only silence there. And we will now break this silence.</p><p>Rosenkranz presses a button. The sound of an old tape deck crackles through the speakers in the hall.</p><hr><h2 id="scene-15-the-advisory-board-in-the-mist" tabindex="-1">Scene 15: The Advisory Board in the Mist <a class="header-anchor" href="#scene-15-the-advisory-board-in-the-mist" aria-label="Permalink to &quot;Scene 15: The Advisory Board in the Mist&quot;">​</a></h2><p><strong>Location:</strong> The meeting room of the COFAG inquiry committee. <strong>Time:</strong> May 2024 (flashback).</p><p>René Benko (Oliver Masucci) sits on the witness stand. He is accompanied by two judicial guards (police demonstration). Walter Rosenkranz (August Diehl) chairs.</p><p><strong>ROSENKRANZ</strong> (with a cutting voice) Mr. Benko, 18.7 million euros in COFAG grants. Why did Chalet N in Lech receive 1.1 million euros while small taverns were fighting for their survival?</p><p><strong>BENKO</strong> (calmly, almost bored) Mr. President, I must decline to answer. Ongoing proceedings. But one thing I want to make clear: In all these companies I was merely... an advisor. A friendly guest in my own properties. I didn&#39;t make any operational decisions. I merely... observed visionary.</p><p><strong>ROSENKRANZ</strong> Observed visionary? You were on a first-name basis with the Federal Chancellor and flew ministers around in your jet!</p><p><strong>BENKO</strong> That too was purely observational. You simply see better from a plane where the gaps in the budget are. And as for the 18 million: those are just many small dots. Pointillism, Mr. President. You surely understand that.</p><hr><h2 id="scene-16-the-whore-for-the-rich" tabindex="-1">Scene 16: The Whore for the Rich <a class="header-anchor" href="#scene-16-the-whore-for-the-rich" aria-label="Permalink to &quot;Scene 16: The Whore for the Rich&quot;">​</a></h2><p><strong>Location:</strong> A chic penthouse office in the Golden Quarter, Vienna. <strong>Time:</strong> December 2016 (flashback).</p><p>Thomas Schmid (August Diehl) stands at the window and looks over the city. Behind him sits René Benko (Oliver Masucci) at a massive desk. He pushes an envelope (or a tablet with a draft contract) across the table.</p><p><strong>BENKO</strong> Thomas, you&#39;re wasting your talent at the ministry. 300,000 fixed, 300,000 bonus. General plenipotentiary at Signa. That would suit you well.</p><p><strong>SCHMID</strong> (turns around slowly, a tortured smile on his lips) René, that is... a generous offer. But I still have tasks here. The tax audits, the coordination with HBK...</p><p><strong>BENKO</strong> Exactly. You clear the hurdles out of the way, and we build the skyscrapers. It&#39;s a synergy, Thomas.</p><p><strong>SCHMID</strong> (whispering, almost to himself) Do you know what I wrote to myself in a chat recently? That I&#39;m hacking in the ÖVP cabinet. That I&#39;m the whore for the rich.</p><p><strong>BENKO</strong> (laughs out loud) But Thomas! You&#39;re not a whore. You&#39;re a service provider of the highest category. And service at this level... it&#39;s paid excellently. Welcome to the team.</p><hr><h2 id="scene-17-the-aesthetic-of-amnesia" tabindex="-1">Scene 17: The Aesthetic of Amnesia <a class="header-anchor" href="#scene-17-the-aesthetic-of-amnesia" aria-label="Permalink to &quot;Scene 17: The Aesthetic of Amnesia&quot;">​</a></h2><p><strong>Location:</strong> Blümel&#39;s modern Viennese apartment. <strong>Time:</strong> A morning in February 2021 (flashback).</p><p>Gernot Blümel (August Diehl in a double role) stands in his pajamas in the hallway. There is a stormy ringing at the door. He looks through the peephole. Outside stand men in windbreakers labeled &quot;WKStA&quot;.</p><p><strong>GERNOT</strong> (hectically whispering to his partner) Darling, they&#39;re here! The... art collectors from the prosecutor&#39;s office. Take the little one. And take the laptop.</p><p><strong>PARTNER</strong> (Oliver Masucci in women&#39;s clothing/wig) Gernot, why should the laptop go in the stroller? The little one already has his iPad.</p><p><strong>GERNOT</strong> It&#39;s a learning project! Early childhood data collection. Go for a walk. Very inconspicuous. If they ask: You know nothing. I know nothing either. We are a family of the pure present. We have no past and definitely no laptop.</p><p><strong>WKStA OFFICIALS (Off)</strong> Open the door! House search!</p><p><strong>GERNOT</strong> (breathes deeply, puts on his best smile and opens the door) Good morning, gentlemen! Do come in. Are you looking for something specific? A piano, perhaps? Or a few donation receipts? I must warn you, though: my memory has its day off today.</p><hr><h2 id="scene-18-the-final-curtain-of-silence" tabindex="-1">Scene 18: The Final Curtain of Silence <a class="header-anchor" href="#scene-18-the-final-curtain-of-silence" aria-label="Permalink to &quot;Scene 18: The Final Curtain of Silence&quot;">​</a></h2><p><strong>Location:</strong> An empty stage. <strong>Time:</strong> Now.</p><p>The three actors (Diehl, Masucci, Minichmayr) step out of their roles. They take off their costumes.</p><p><strong>AUGUST DIEHL</strong> Is it true? <strong>OLIVER MASUCCI</strong> It&#39;s better than true. It&#39;s documented. <strong>BIRGIT MINICHMAYR</strong> It&#39;s a mockumentary. We can tell the truth as long as we claim it&#39;s invented.</p><p>They look into the camera together. In the background, we see the logo of the website: <em>The Horten Mystery</em>.</p><p><strong>FADE OUT.</strong></p><h1 id="the-research-archive" tabindex="-1">THE RESEARCH ARCHIVE <a class="header-anchor" href="#the-research-archive" aria-label="Permalink to &quot;THE RESEARCH ARCHIVE&quot;">​</a></h1><hr><h1 id="research-the-shredder-affair-reisswolf-gate" tabindex="-1">Research: The Shredder Affair (Reisswolf-Gate) <a class="header-anchor" href="#research-the-shredder-affair-reisswolf-gate" aria-label="Permalink to &quot;Research: The Shredder Affair (Reisswolf-Gate)&quot;">​</a></h1><p>In the context of our mockumentary, we shed light not only on the historical machinations of the Horten era, but also on the modern ethics of political transparency. A prime example of handling &quot;unpleasant data&quot; is the Austrian Shredder Affair of 2019.</p><h2 id="the-incident" tabindex="-1">The Incident <a class="header-anchor" href="#the-incident" aria-label="Permalink to &quot;The Incident&quot;">​</a></h2><p>Shortly after the Ibiza video became known, a close confidant of then-Chancellor Sebastian Kurz, under the pseudonym &quot;Walter Maisinger,&quot; brought five hard drives to the <em>Reisswolf</em> company. He had them shredded three times, took the remains back with him, and forgot to pay the bill – which blew the entire operation.</p><hr><h1 id="research-the-eurofighter-affair-the-most-expensive-toy" tabindex="-1">Research: The Eurofighter Affair (The Most Expensive Toy) <a class="header-anchor" href="#research-the-eurofighter-affair-the-most-expensive-toy" aria-label="Permalink to &quot;Research: The Eurofighter Affair (The Most Expensive Toy)&quot;">​</a></h1><p>In our mockumentary, the Eurofighter scandal serves as the ultimate example of &quot;offset deals&quot; and what Dr. von Zitzewitz calls &quot;creative armament diplomacy.&quot;</p><h2 id="the-core-of-the-scandal" tabindex="-1">The Core of the Scandal <a class="header-anchor" href="#the-core-of-the-scandal" aria-label="Permalink to &quot;The Core of the Scandal&quot;">​</a></h2><p>Since 2002, this armament purchase has occupied the Austrian justice system. It involves 15 to 18 fighter jets, hundreds of millions in suspected bribes, and a web of shell companies that makes even professionals dizzy.</p><hr><h1 id="research-the-advertisement-affair-bought-opinion" tabindex="-1">Research: The Advertisement Affair (Bought Opinion) <a class="header-anchor" href="#research-the-advertisement-affair-bought-opinion" aria-label="Permalink to &quot;Research: The Advertisement Affair (Bought Opinion)&quot;">​</a></h1><p>In our mockumentary, we investigate how favor in the press is not only earned but simply bought. The advertisement affair of the Kurz era is the textbook example for the 21st century.</p><hr><h1 id="research-political-patronage-the-thomas-schmid-chats" tabindex="-1">Research: Political Patronage &amp; The Thomas Schmid Chats <a class="header-anchor" href="#research-political-patronage-the-thomas-schmid-chats" aria-label="Permalink to &quot;Research: Political Patronage &amp; The Thomas Schmid Chats&quot;">​</a></h1><p>&quot;You&#39;ll get everything you want.&quot; – This sentence from Thomas Schmid&#39;s chats has become a symbol of politics that views the state as a self-service shop for cronies.</p><hr><h1 id="research-the-postenschacher-case-august-woginger" tabindex="-1">Research: The &quot;Postenschacher&quot; Case (August Wöginger) <a class="header-anchor" href="#research-the-postenschacher-case-august-woginger" aria-label="Permalink to &quot;Research: The &quot;Postenschacher&quot; Case (August Wöginger)&quot;">​</a></h1><p><strong>The case of the parliamentary group leader: When political intervention meets abuse of office.</strong></p><p>Parallel to the historical machinations of the Horten era, the current political landscape of Austria provides ample material for our mockumentary. A prime example of modern intervention is the trial against ÖVP parliamentary group leader <strong>August Wöginger</strong>, who is currently (as of February/March 2026) standing trial at the Linz Regional Court.</p><hr><h1 id="research-the-modern-power-circles-of-the-ovp" tabindex="-1">Research: The Modern Power Circles of the ÖVP <a class="header-anchor" href="#research-the-modern-power-circles-of-the-ovp" aria-label="Permalink to &quot;Research: The Modern Power Circles of the ÖVP&quot;">​</a></h1><p><strong>From the &quot;New Style&quot; to the Billion-Dollar Deficit: The Continuation of Pointillism.</strong></p><hr><h1 id="research-the-benko-connection-horten-s-legacy-at-signa" tabindex="-1">Research: The Benko Connection (Horten&#39;s Legacy at Signa) <a class="header-anchor" href="#research-the-benko-connection-horten-s-legacy-at-signa" aria-label="Permalink to &quot;Research: The Benko Connection (Horten&#39;s Legacy at Signa)&quot;">​</a></h1><p><strong>From the Department Store King to the Real Estate Speculator: The Circle Closes.</strong></p><hr><h1 id="research-the-case-of-christian-pilnacek" tabindex="-1">Research: The Case of Christian Pilnacek <a class="header-anchor" href="#research-the-case-of-christian-pilnacek" aria-label="Permalink to &quot;Research: The Case of Christian Pilnacek&quot;">​</a></h1><p><strong>The secret audio recordings and the &quot;shutting down&quot; of investigations.</strong></p><hr><h1 id="research-walter-rosenkranz-chair-of-the-pilnacek-committee" tabindex="-1">Research: Walter Rosenkranz (Chair of the Pilnacek Committee) <a class="header-anchor" href="#research-walter-rosenkranz-chair-of-the-pilnacek-committee" aria-label="Permalink to &quot;Research: Walter Rosenkranz (Chair of the Pilnacek Committee)&quot;">​</a></h1><p><strong>The new referee in the Archive of Silence.</strong></p><hr><h1 id="research-corruption-of-fpo-and-ovp-international-perspectives" tabindex="-1">Research: Corruption of FPÖ and ÖVP (International Perspectives) <a class="header-anchor" href="#research-corruption-of-fpo-and-ovp-international-perspectives" aria-label="Permalink to &quot;Research: Corruption of FPÖ and ÖVP (International Perspectives)&quot;">​</a></h1><hr><h1 id="secret-media-documents" tabindex="-1">Secret Media &amp; Documents <a class="header-anchor" href="#secret-media-documents" aria-label="Permalink to &quot;Secret Media &amp; Documents&quot;">​</a></h1><p>Here we collect the (fictional) evidence supporting our mockumentary. Warning: Some of these documents are considered &quot;non-existent&quot; in certain circles.</p><h2 id="📄-leaked-the-sacher-napkin-reconstruction" tabindex="-1">📄 Leaked: The &quot;Sacher Napkin&quot; (Reconstruction) <a class="header-anchor" href="#📄-leaked-the-sacher-napkin-reconstruction" aria-label="Permalink to &quot;📄 Leaked: The &quot;Sacher Napkin&quot; (Reconstruction)&quot;">​</a></h2><p>This document forms the heart of Part 4. It is an original napkin from the Hotel Sacher, on which Heidi&#39;s handwriting (and a lipstick print on the edge) captured the first strategic sketch of the &quot;pointillism donations.&quot;</p><h2 id="📜-archive-find-the-purchase-contract" tabindex="-1">📜 Archive Find: The &quot;Purchase Contract&quot; <a class="header-anchor" href="#📜-archive-find-the-purchase-contract" aria-label="Permalink to &quot;📜 Archive Find: The &quot;Purchase Contract&quot;&quot;">​</a></h2><p>A draft document for the takeover of the Alsberg houses from 1933. The price was corrected several times with red pen until it was almost zero. A handwritten note on the margin reads: <em>&quot;Standard. Efficient. Done.&quot;</em></p><h2 id="🎙️-audio-protocol-the-pub-testament" tabindex="-1">🎙️ Audio Protocol: &quot;The Pub Testament&quot; <a class="header-anchor" href="#🎙️-audio-protocol-the-pub-testament" aria-label="Permalink to &quot;🎙️ Audio Protocol: &quot;The Pub Testament&quot;&quot;">​</a></h2><p>A transcript of the secretly recorded tapes of Christian Pilnacek from a Viennese pub (November 2023).</p>',266)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
